head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF05232";
scwin.isSpac = false;           // 기업인수목적회사 메뉴(STF05265)로 열렸는가 (AS-IS pMenuID)
scwin.spacYN = "N";             // 상장폐지사유 찾기에 넘기는 기업인수목적회사 구분 (AS-IS spacYN)
scwin.userMkt = "";             // 사용자 시장구분 — 6 이면 코넥스 화면 (AS-IS js_market)
scwin.isurCd = "";              // 선택한 회사코드 (AS-IS txb_ISUR_CD)
scwin.secugrpId = "";           // 증권그룹ID — 회사 선택 결과로 바뀐다 (AS-IS fr_SecuGrpId)
scwin.mktTpCd = "";             // 회사 시장구분 1: 유가, 2: 코스닥, 6: 코넥스 (AS-IS vSPOT_ISU_TRD_MKT_TP_CD)
scwin.bzProcsNo = "";           // 선택한 상장폐지 건의 업무처리번호 — 비면 신규 (AS-IS vBzProcsNo)
scwin.trJob = "";               // 처리구분 I: 저장, U: 수정, D: 삭제 (AS-IS trsIdx)
scwin.savedState = "";          // 상세를 채운 직후의 값 — 안내문작성 전 변경 여부 판정용 (AS-IS dts_Mst.IsUpdated)
scwin.MENU_CD_SPAC = "05265";                   // 기업인수목적회사 메뉴 코드 끝자리 — TODO: TO-BE 메뉴 코드 체계 확인 (§10 #6)
scwin.MKTACT_APPL_OBJ_TP_CD = "2";              // 시장조치적용대상구분 1: 종목별, 2: 법인별 — 이 화면은 법인별
scwin.RSNCD_DELIST = "4";                       // 사유 찾기 구분 — 상장폐지사유 (pcc list_common RSNCD_DELIST)
scwin.GRND_REGUL_MANUAL = "직접 입력하세요";      // 근거규정 「수기 입력」 항목의 값
scwin.DSCL_FORM_CD_KSE = "68051A";              // 공시안내문 서식코드 — 유가 (AS-IS fn_dscl 의 arr[0])
scwin.DSCL_FORM_CD_KOSDAQ = "70769";            // 공시안내문 서식코드 — 코스닥
scwin.DSCL_FORM_CD_KONEX = "32007";             // 공시안내문 서식코드 — 코넥스
scwin.DSCL_FORM_CD_MF = "70794";                // 공시안내문 서식코드 — 투자회사(MF), 액면가 있음
scwin.DSCL_FORM_CD_MF_NPARVAL = "70794_P";      // 공시안내문 서식코드 — 투자회사(MF), 무액면
// 원본 : /lstproc/ULDSTF05232.gfm (상장폐지(회사별) — 메뉴 STF05232 주권, STF05265 기업인수목적회사가 같은 화면을 쓴다)
/*
 * 화면 동작
 *  - [회사 찾기]로 회사를 고르면 그 회사의 상장폐지내역(갯수·목록)과 현재 상장 종목을 조회하고 빈 상세(신규)로 둔다.
 *  - 상장폐지내역 행을 누르면 그 건을 상세에 채우고, 상장폐지일이 지나지 않았거나 공시되지 않은 건만 수정·삭제·안내문작성할 수 있다.
 *  - 회사 시장구분(1 유가 / 2 코스닥 / 6 코넥스)에 따라 상장폐지사유 입력 방식·예고기간·상장주선인 찾기가 바뀐다.
 *  - 사용자 시장이 코넥스(6)면 지정자문인(특례상장구분)·이전상장구분·비고(코넥스)를 보인다.
 *  - 신규 API 명세는 조회 3종(갯수·목록·종목)뿐이다. 상세·저장·수정·삭제·영문 조회 API 가 없어
 *    상세는 목록 행 값으로 채우고, 저장·수정·삭제는 검증·확인까지만 하고 서버를 부르지 않는다(TODO §10 #1·#2).
 *  - 공시안내문작성(ULDSTF92024)·기안(ULDSTF92004)은 openPopup 의 data 로 넘기고 await 한다.
 *    92024 전환본이 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 만 임시로 둔다(§10 #8).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05232/ULDSTF05232.md (§번호는 이 문서의 절)
 */

// 진입·세션에서 정하는 값 (§1.2)

// 화면 상태값

// 고정값
scwin.JOB_NM = { I : "저장", U : "수정", D : "삭제" };
// 근거규정 목록 — 사용자 시장이 코넥스(6)일 때 / 그 밖 (AS-IS gform onload 의 CBData)
scwin.GRND_REGUL_LIST_KONEX = [
    { label : "코넥스시장상장규정 제28조 및 제33조", value : "코넥스시장상장규정 제28조 및 제33조" },
    { label : "수기 입력", value : "직접 입력하세요" }
];
scwin.GRND_REGUL_LIST = [
    { label : "유가증권시장상장규정 제48조", value : "유가증권시장상장규정 제48조" },
    { label : "코스닥시장상장규정 제23조 및 제54조", value : "코스닥시장상장규정 제23조 및 제54조" },
    { label : "코스닥시장상장규정 제23조 및 제82조", value : "코스닥시장상장규정 제23조 및 제82조" },
    { label : "코스닥시장상장규정 제54조 및 제73조", value : "코스닥시장상장규정 제54조 및 제73조" },
    { label : "수기 입력", value : "직접 입력하세요" }
];

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
// [신규]는 원본 buttonSet 밖의 버튼이라 늘 활성이다(§4).
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    draft : "btn_Drft",         // [기안]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05232.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — 메뉴·세션 값 → 사용자 시장별 화면(코넥스 항목·근거규정 목록·공통 코드) → 달력 바인딩 → 빈 상세(신규).
 * 회사를 고르기 전이라 조회는 하지 않는다. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 메뉴·세션 값 — 원본 InfoMenuID()·js_market
    const menuInfo = $c.data.getParameter("menuInfo") ?? {};
    scwin.isSpac = String(menuInfo.menuCode ?? "").endsWith(scwin.MENU_CD_SPAC);
    scwin.spacYN = scwin.isSpac ? "Y" : "N";
    scwin.secugrpId = $c.lc.glb.SECUGRP_ID_ST;      // 두 메뉴 모두 주권(ST) — 원본 fn_getSecuGrpId(InfoMenuID())
    scwin.userMkt = String($c.session.getUserInfo("market") ?? "");

    // 2) 사용자 시장별 화면 — 코넥스 항목 표시·근거규정 목록·공통 코드 (§6.1)
    await scwin.setUserMktView();

    // 3) 달력 검사 바인딩(1회) — 단일 달력은 checkCalendarFormat, 기간 쌍은 compareFromToDate 만(규칙 37)
    $c.date.checkCalendarFormat(edt_DELIST_DD, "yyyyMMdd");
    $c.date.compareFromToDate(edt_DELIST_ADVNOTI_STRT_DD, edt_DELIST_ADVNOTI_END_DD, ["상장폐지예고 시작일", "상장폐지예고 종료일"]);
    $c.date.compareFromToDate(edt_ARRANTRD_MKTACT_ENFORCE_DD, edt_ARRANTRD_END_DD, ["정리매매허용 시작일", "정리매매허용 종료일"]);

    // 4) 빈 상세 · 신규 버튼 상태 — 원본 buttonSet.setInsertStatus() + dts_Mst.AddRow()
    scwin.initItem();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_COM_NM_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 회사 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_COM_NM_onclick = async function (e) {
    try {
        await scwin.openCompanyPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05232.img_COM_NM_onclick" });
    }
};

