/**
 * @method
 * @name scwin.cmb_GRND_REGUL_NM_onviewchange
 * @author Inswave
 * @date 2026. 10. 28
 * @description 근거규정 목록 선택 — 고른 규정을 근거규정 입력칸에 옮긴다. (원본 cmb_GRND_REGUL_NM OnSelChange)
 * @param {Object} info 이벤트 정보 객체
 * @returns
 * @hidden N
 */
scwin.cmb_GRND_REGUL_NM_onviewchange = async function (info) {
    try {
        scwin.applyGrndRegul(cmb_GRND_REGUL_NM.getValue());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05232.cmb_GRND_REGUL_NM_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.cmb_SPECL_LIST_TP_CD_onviewchange
 * @author Inswave
 * @date 2026. 10. 28
 * @description 특례상장구분(지정자문인, 코넥스) 선택 — 값을 고르면 상장주선인을 비운다. (원본 cmb_SPECL_LIST_TP_CD OnSelChange)
 * @param {Object} info 이벤트 정보 객체
 * @returns
 * @hidden N
 */
scwin.cmb_SPECL_LIST_TP_CD_onviewchange = async function (info) {
    try {
        if (!$c.util.isEmpty(cmb_SPECL_LIST_TP_CD.getValue())) {
            dma_mst.set("mktpartcKorNm", "");
            dma_mst.set("listAgnccomMbrNo", "");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05232.cmb_SPECL_LIST_TP_CD_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncellclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장폐지내역 행 클릭 — 그 건을 상세에 채운다. (원본 grd_List OnClick → fn_OpenDetail + fn_chkIsu)
 * @param {Number} rowIndex 행 index
 * @param {Number} columnIndex 열 index
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        scwin.openDetail(rowIndex);
        // TODO: 원본 fn_chkIsu(공시된 건의 상장주식수가 바뀌었으면 확인 후 다시 읽어 수정) 는 보류 —
        //       등록 종목 조회(listMarket) API 가 명세에 없어 비교할 등록 주식수가 없다 (§6.9, §10 #3)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05232.grd_List_oncellclick" });
    }
};

