///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectCount
 * @author Inswave
 * @date 2026. 10. 28
 * @description 회사별 상장폐지 갯수 조회 (명세 select-count — AS-IS 대응 통신 없음, §5.1). 갯수를 상장폐지내역 총건수로 쓴다.
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectCount = async function () {
    const sbmOptions = {
        id : "sbm_selectCount",
        method : "get",
        action : "/api/listing/lstproc/stock/delisting-com/select-count",
        target : "dma_cnt=body",
        isProcessMsg : false
    };

    dma_cnt.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : scwin.isurCd, mktactApplObjTpCd : scwin.MKTACT_APPL_OBJ_TP_CD });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    return result.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장폐지내역 조회 — 법인별(2) 건만. (원본 fn_list_sync — listMarketDetail, §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/stock/delisting-com/select-list",
        target : "dlt_list2=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : scwin.isurCd, mktactApplObjTpCd : scwin.MKTACT_APPL_OBJ_TP_CD });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    return result.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectIsuList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 회사의 상장폐지 대상 종목·주식수 조회 (원본 fn_new_read_sync — listMarketNew, §5.3)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectIsuList = async function () {
    const sbmOptions = {
        id : "sbm_selectIsuList",
        method : "get",
        action : "/api/listing/lstproc/stock/delisting-com/select-list-isu",
        target : "dlt_list=body",
        gridview : "grd_Isu",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : scwin.isurCd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    return result.responseJSON?.success === true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장(I)·수정(U)·삭제(D) 전송. 법인별(2)로 처리한다. (원본 fn_trs + trs_Save OnSuccess/OnFail — §5.6)
 * 명세에 저장·수정·삭제 API 가 없어 지금은 서버를 부르지 않고 안내만 한다.
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @returns {Promise<Boolean>} 처리 성공 여부 (지금은 늘 false)
 * @hidden N
 */
scwin.saveTrs = async function (trJob) {
    const jobNm = scwin.JOB_NM[trJob] ?? "";

    // 원본 fn_trs — 법인별 기준으로 처리(1: 종목별, 2: 법인별)
    dma_mst.set("mktactApplObjTpCd", scwin.MKTACT_APPL_OBJ_TP_CD);

    // TODO: 저장·수정·삭제 API 명세 없음 (§5.6, §10 #1) — 명세를 받으면 아래처럼 보낸다.
    //       id "sbm_saveTrs", method "post", action 명세 경로(처리구분마다 전체 경로 리터럴),
    //       요청 = dma_mst(+ 업무처리번호·회사코드) + 종목 목록 dlt_list(행마다 bzProcsNo — 원본 dts_Isu),
    //       업무구분 LIST_BZ_TP_CD 200($c.lc.glb.LIST_BZ_TP_CD_200) 을 서버가 받는지 확인,
    //       성공이면 MSG-A001 안내 뒤 await scwin.listSync()(원본 OnSuccess 의 fn_list_sync), 실패면 MSG-A002.
    // TODO: 가정 문구 (§7, §10 #1)
    await $c.win.alert("상장폐지 " + jobNm + " API 가 정해지지 않아 처리할 수 없습니다.");
    return false;
};

/**
 * @method
 * @name scwin.setUserMktView
 * @author Inswave
 * @date 2026. 10. 28
 * @description 사용자 시장별 화면. 코넥스(6)면 특례상장구분·이전상장구분·비고(코넥스)를 보이고 공통 코드를 받는다.
 * 근거규정 목록도 시장별로 다르다. (원본 gform onload 의 js_market 분기 + fn_searchCode — §6.1)
 * @returns
 * @hidden N
 */
scwin.setUserMktView = async function () {
    const isKonex = (scwin.userMkt === "6");

    [cmb_SPECL_LIST_TP_CD, tr_PRE_LIST_TP_CD, tr_DSC].forEach(comp => {
        if (isKonex) {
            comp.show("");
        } else {
            comp.hide();
        }
    });

    dlt_grndRegul.setJSON(isKonex ? scwin.GRND_REGUL_LIST_KONEX : scwin.GRND_REGUL_LIST);

    if (isKonex) {
        // AS-IS /CodeAction.do listCodeValueNameM (첫 항목 "선택")
        await $c.data.setCommonCode([
            { code : ["SPECL_LIST_TP_CD", "PRE_LIST_TP_CD"], compID : ["cmb_SPECL_LIST_TP_CD", "cmb_PRE_LIST_TP_CD"], firstRow : ["", "선택"] }
        ]);
    }
};

/**
 * @method
 * @name scwin.openCompanyPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 회사 찾기. 기업인수목적회사 메뉴면 SPAC 회사("1"), 아니면 주권 회사("2") 목록에서 고른다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 img_COM_NM onclick + fn_GetParIsur/fn_SetParIsur + fn_PopFindCorpChrgSW — §6.2)
 * @returns
 * @hidden N
 */
scwin.openCompanyPopup = async function () {
    // 92009_SW 는 행을 더블클릭했을 때만 DBCLICKYN "Y" 와 회사를 돌려준다. 취소·닫기(X)는 { isCloseButtonClick } 객체다.
    const res = await $c.lc.popFindCorpChrgSW(scwin.secugrpId, scwin.isSpac ? "1" : "2");
    if (res?.DBCLICKYN !== "Y" || $c.util.isEmpty(res?.ISUR_CD)) return;

    await scwin.setCompany(res);
};

/**
 * @method
 * @name scwin.setCompany
 * @author Inswave
 * @date 2026. 10. 28
 * @description 고른 회사를 화면에 반영한다 — 라벨·입력 방식(시장구분) → 빈 상세 → 내역·종목 조회 → 담당 부서 버튼 잠금. (원본 fn_SetParIsur — §6.2)
 * @param {Object} res 회사 선택 결과 { ISUR_CD, COM_NM, SPOT_ISU_TRD_MKT_TP_CD, SECUGRP_ID }
 * @returns
 * @hidden N
 */
scwin.setCompany = async function (res) {
    scwin.isurCd = String(res.ISUR_CD ?? "");
    scwin.secugrpId = String(res.SECUGRP_ID ?? "") || scwin.secugrpId;
    scwin.mktTpCd = String(res.SPOT_ISU_TRD_MKT_TP_CD ?? "");
    dma_search.set("isurCd", scwin.isurCd);
    dma_search.set("comNm", res.COM_NM ?? "");

    scwin.setLeadComLabel();
    scwin.setComponentByMkt();
    scwin.initItem();
    await scwin.listSync();

    // 담당 부서가 아니면 처리 버튼을 잠근다(원본 buttonSet.setButtonDepCd). 상태 지정 뒤에 둬야 잠금이 남는다(§8 #9).
    await $c.lc.setButtonDepCd(scwin.isurCd, $c.session.getUserInfo() ?? {}, [btn_Save, btn_Update, btn_Delete, btn_Drft, btn_Dscl]);
};

/**
 * @method
 * @name scwin.setLeadComLabel
 * @author Inswave
 * @date 2026. 10. 28
 * @description 8번 항목 라벨. 코넥스 회사면 "지정자문인(코넥스)"(필수 아님), 그 밖은 "상장주선인(코)"(필수 표시). (원본 fn_SetParIsur 의 showObj — §6.2)
 * @returns
 * @hidden N
 */
scwin.setLeadComLabel = function () {
    if (scwin.mktTpCd === "6") {
        label_24.show("");
        label_18.hide();
    } else {
        label_24.hide();
        label_18.show("");
    }
};

/**
 * @method
 * @name scwin.setComponentByMkt
 * @author Inswave
 * @date 2026. 10. 28
 * @description 회사 시장구분별 입력 방식. 유가는 사유를 찾기로만 고르고 상장주선인 찾기를 잠근다.
 * 코스닥·코넥스는 사유를 직접 입력하고 예고기간을 비워 잠그며, 이전상장구분·비고는 코넥스만 쓴다. (원본 fn_setComponent — §6.3)
 * @returns
 * @hidden N
 */
scwin.setComponentByMkt = function () {
    const advnotiComps = [edt_DELIST_ADVNOTI_STRT_DD, edt_DELIST_ADVNOTI_END_DD, txb_DELIST_ADVNOTI_PD_DSC];

    if (scwin.mktTpCd === "1") {
        img_DELIST_RSN_DSC.setDisabled(false);
        txb_DELIST_RSN_DSC.setReadOnly(true);
        img_MKTPARTC_KOR_NM.setDisabled(true);
        // 코스닥 회사 뒤 유가 회사를 고르면 예고기간이 잠긴 채 남던 원본 결함을 고친다(§8 #4).
        advnotiComps.forEach(comp => comp.setReadOnly(false));
    } else if (scwin.mktTpCd === "2" || scwin.mktTpCd === "6") {
        img_DELIST_RSN_DSC.setDisabled(true);
        txb_DELIST_RSN_DSC.setReadOnly(false);
        img_MKTPARTC_KOR_NM.setDisabled(false);

        ["delistAdvnotiStrtDd", "delistAdvnotiEndDd", "delistAdvnotiPdDsc", "preListTpCd", "dsc"].forEach(key => dma_mst.set(key, ""));
        advnotiComps.forEach(comp => comp.setReadOnly(true));

        const isKonex = (scwin.mktTpCd === "6");
        cmb_PRE_LIST_TP_CD.setDisabled(!isKonex);
        txa_DSC.setDisabled(!isKonex);
    }
};

/**
 * @method
 * @name scwin.listSync
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장폐지내역 조회 → 총건수 → 빈 상세(신규) → 종목 조회. (원본 fn_list_sync + dts_List OnLoadCompleted — §5.1·§5.2·§5.3)
 * @returns
 * @hidden N
 */
scwin.listSync = async function () {
    const cntOk = await scwin.selectCount();
    if (!await scwin.selectList()) return;    // 실패는 공통 오류 핸들러가 안내 — 원본 OnLoadError 처럼 상세는 그대로 둔다

    // 총건수 — 명세 select-count 의 cnt, 받지 못했으면 목록 행 수 (TODO: cnt 와 행 수의 관계 확인 §10 #4)
    const cnt = (cntOk && !$c.util.isEmpty(dma_cnt.get("cnt"))) ? Number(dma_cnt.get("cnt")) : dlt_list2.getRowCount();
    $c.stf.fillGridHeaderTotalCnt(cnt, panel_page);

    scwin.initItem();
    await scwin.selectIsuList();
};

/**
 * @method
 * @name scwin.initItem
 * @author Inswave
 * @date 2026. 10. 28
 * @description 빈 상세(신규). 버튼은 insert, 종목·상세·업무처리번호·근거규정 선택을 비운다. 통신 없음. (원본 fn_initItem — §6.4)
 * @returns
 * @hidden N
 */
scwin.initItem = function () {
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    dlt_list.removeAll();
    dma_mst.setEmptyValue();
    scwin.bzProcsNo = "";
    scwin.savedState = "";
    cmb_GRND_REGUL_NM.setValue("");
    txb_GRND_REGUL_NM.setReadOnly(false);    // 근거규정 입력칸을 처음 상태(직접 입력 가능)로 — §8 #6
};

/**
 * @method
 * @name scwin.newItem
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규. 회사를 고른 뒤에만 빈 상세로 두고 종목을 다시 조회한다. (원본 btn_New onclick — §6.4)
 * @returns
 * @hidden N
 */
scwin.newItem = async function () {
    if ($c.util.isEmpty(scwin.isurCd)) {
        await $c.win.alert("회사를 선택하세요");
        return;
    }
    scwin.initItem();
    await scwin.selectIsuList();
};

/**
 * @method
 * @name scwin.openDetail
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장폐지내역 행을 상세에 채우고 버튼 상태를 정한다. 상세 조회 API 가 없어 목록 행 값(같은 이름 키)으로 채운다.
 * (원본 fn_OpenDetail + dts_Mst OnLoadCompleted — §6.5)
 * @param {Number} rowIndex 상장폐지내역 행 index
 * @returns
 * @hidden N
 */
scwin.openDetail = function (rowIndex) {
    const row = dlt_list2.getRowJSON(rowIndex);
    scwin.bzProcsNo = String(row.bzProcsNo ?? "");

    // TODO: 상세 조회 API 명세 없음 (§10 #2) — 원본 masterDetail·listMarket·masterDetailEng·listMarketEng 4회 조회 대신
    //       목록 행에 있는 키만 옮긴다. 예고기간·정리매매기간·주석·특례상장구분·이전상장구분·비고(코넥스)는 비어 있고,
    //       종목 목록은 그 건의 등록 종목이 아니라 회사의 현재 종목(select-list-isu)이 그대로 남는다.
    const mst = {};
    Object.keys(dma_mst.getJSON()).forEach(key => {
        if (key in row) mst[key] = row[key] ?? "";
    });
    mst.isurCd = scwin.isurCd;

    dma_mst.setEmptyValue();
    dma_mst.setJSON(mst);

    scwin.applyButtonState();
    scwin.savedState = scwin.getEditState();
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상세를 채운 뒤 버튼 상태. 업무처리번호가 없으면 insert, 상장폐지일이 오늘 이후면 update,
 * 지났으면 error(기안만)이되 공시되지 않은 건은 update 로 덮는다. (원본 dts_Mst OnLoadCompleted — §6.5, §8 #5)
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        return;
    }
    if ($c.date.getServerDateTime("yyyyMMdd") <= dma_mst.get("delistDd")) {
        $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
        return;
    }
    $c.util.setButtonState("grpBtnBox", "error", scwin.BTN_MAP);
    $c.stf.setButtonSetWithDate2(dma_mst.get("disclsYn"), "grpBtnBox", scwin.BTN_MAP);    // 미공시 → update 로 덮어씀
};

/**
 * @method
 * @name scwin.getEditState
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상세 입력값의 현재 상태 문자열 — 채운 직후 값과 비교해 바뀌었는지 본다. (원본 dts_Mst.IsUpdated — §6.10)
 * @returns {String} 상세 입력값 JSON 문자열
 * @hidden N
 */
scwin.getEditState = function () {
    return JSON.stringify(dma_mst.getJSON());
};

/**
 * @method
 * @name scwin.openRsnPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장폐지사유 찾기(ULDSTF92008). 고른 사유 코드·사유·근거규정을 상세에 채운다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 img_DELIST_RSN_DSC onclick + fn_GetParRsn/fn_SetParRsn + fn_PopFindClssLstRsnCd — §6.6)
 * @returns
 * @hidden N
 */
scwin.openRsnPopup = async function () {
    // AS-IS arr[0] "K", arr[1] "05", arr[5] 기업인수목적회사 구분 — TODO: 92008 수신 키(mkt·rsn·spac) 대응은 가정 (§10 #7)
    const res = await $c.lc.popFindClssLstRsnCd(scwin.RSNCD_DELIST, { mkt : "K", rsn : "05", spac : scwin.spacYN });
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.code)) return;    // 취소·닫기

    dma_mst.set("delistRsnCd", res.code);
    dma_mst.set("delistRsnDsc", res.name ?? "");
    // TODO: 근거규정(AS-IS arr[2]) — 92008 전환본은 code·name 만 돌려준다. 키 이름(regl)은 가정 (§10 #7)
    dma_mst.set("grndRegulNm", res.regl ?? "");
};

/**
 * @method
 * @name scwin.openLeadComPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장주선인(지정자문인) 찾기(ULDSTF92014). 고른 회원번호·이름을 상세에 채운다. 취소·닫기면 아무것도 하지 않는다.
 * pcc $c.lc.popFindLeadComSingle 은 결과를 돌려주지 않는 콜백형이라 쓰지 않는다. (원본 fn_SetParMbrNo + fn_PopFindLeadCom2 — §6.7)
 * @returns
 * @hidden N
 */
scwin.openLeadComPopup = async function () {
    const options = {
        id : "ULDSTF92014",
        popupName : (scwin.userMkt === "6") ? "지정자문인 선택" : "상장주선인 선택",
        width : 350,
        height : 545,
        type : "pageFramePopup"
    };

    // TODO: 92014 전환본이 없어 경로·넘기는 키·반환 키(mbrNo·mbrNm)는 가정 (§10 #7)
    const res = await $c.win.openPopup("/ui/lst/common/ULDSTF92014.xml", options, { secugrpId : scwin.secugrpId });
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.mbrNo)) return;    // 취소·닫기

    dma_mst.set("listAgnccomMbrNo", res.mbrNo);       // AS-IS arr[0]
    dma_mst.set("mktpartcKorNm", res.mbrNm ?? "");     // AS-IS arr[1]
};

/**
 * @method
 * @name scwin.applyGrndRegul
 * @author Inswave
 * @date 2026. 10. 28
 * @description 근거규정 목록에서 고른 값을 입력칸에 옮긴다. 「수기 입력」이면 입력칸을 비우고 직접 입력하게 한다. (원본 cmb_GRND_REGUL_NM OnSelChange — §6.8, §8 #6)
 * @param {String} value 고른 근거규정 값
 * @returns
 * @hidden N
 */
scwin.applyGrndRegul = function (value) {
    const manual = (value === scwin.GRND_REGUL_MANUAL);

    dma_mst.set("grndRegulNm", manual ? "" : (value ?? ""));
    txb_GRND_REGUL_NM.setReadOnly(!manual);
    if (manual) txb_GRND_REGUL_NM.focus();
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서를 따른다 — 필수는 원본 문구로, byte 길이는 공통 검증(validateDataCollect)으로,
 * 그 사이에 기간 선후·현재일 비교와 서버 중복 확인을 둔다. (§6.11)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    // 1) 회사 · 종목
    if ($c.util.isEmpty(scwin.isurCd)) {
        await $c.win.alert("[회사]를 선택하세요.");
        return false;
    }
    if (dlt_list.getRowCount() === 0) {
        await $c.win.alert("[상장폐지 종목]을선택하세요");
        return false;
    }

    // 2) 상장폐지사유 — 유가는 찾기로 고른 코드, 코스닥·코넥스는 직접 입력(2000 byte)
    if (scwin.mktTpCd === "1") {
        if ($c.util.isEmpty(dma_mst.get("delistRsnCd"))) {
            await $c.win.alert("[상장폐지사유]를 선택하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }
    } else if (scwin.mktTpCd === "2" || scwin.mktTpCd === "6") {
        if ($c.util.isEmpty(dma_mst.get("delistRsnDsc"))) {
            await $c.win.alert("[상장폐지사유]를 입력하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }
        const rsnOptions = {
            validateType : "alert",
            checkType : "single",
            fields : {
                txb_DELIST_RSN_DSC : { maxLengthB : 2000, name : "상장폐지사유" }
            }
        };
        if (!await $c.validate.validateDataCollect(panel_Top, rsnOptions)) return false;
    }

    // 3) 상장폐지 예고기간 · 4) 정리매매 허용기간 — 하나라도 입력했으면 둘 다 필수, 시작일 ≤ 종료일
    if (!await scwin.validatePeriod(edt_DELIST_ADVNOTI_STRT_DD, edt_DELIST_ADVNOTI_END_DD, "상장폐지예고 시작일", "상장폐지예고 종료일")) return false;
    if (!await scwin.validatePeriod(edt_ARRANTRD_MKTACT_ENFORCE_DD, edt_ARRANTRD_END_DD, "정리매매허용 시작일", "정리매매허용 종료일")) return false;

    // 5) 상장폐지일 필수 · 현재일 이후 (미정이면 9999-12-31)
    const delistDd = dma_mst.get("delistDd");
    if ($c.util.isEmpty(delistDd)) {
        await $c.win.alert("[상장폐지일]을 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if ($c.date.getServerDateTime("yyyyMMdd") >= delistDd) {
        await $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }

    // 6) 근거규정 필수 · 200 byte
    if ($c.util.isEmpty(dma_mst.get("grndRegulNm"))) {
        await $c.win.alert("[근거규정]을 입력하세요.");
        txb_GRND_REGUL_NM.focus();
        return false;
    }
    const grndOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txb_GRND_REGUL_NM : { maxLengthB : 200, name : "근거규정" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_Top, grndOptions)) return false;

    // 7) 코스닥은 상장주선인 필수 (코넥스 지정자문인은 필수 아님)
    if (scwin.mktTpCd === "2" && $c.util.isEmpty(dma_mst.get("listAgnccomMbrNo"))) {
        await $c.win.alert("[상장주선인]를 선택하세요.");
        txb_MKTPARTC_KOR_NM.focus();
        return false;
    }

    // 8) 업무 중복 입력 확인 (같은 회사·상장폐지일에 처리 중인 업무)
    // TODO: pcc checkBzDoubleInput 은 주식 변경상장 경로(stock/chglisting/check-double-input) 이고 첫 인자를 isuCd 로 보낸다 —
    //       상장폐지(200)·회사코드로 불러도 되는지, 응답에 disclsProcsDdtm 이 없을 때 늘 막히는 결함 (§10 #9)
    if (!await $c.lc.checkBzDoubleInput(scwin.isurCd, delistDd, scwin.bzProcsNo, $c.lc.glb.LIST_BZ_TP_CD_200)) return false;

    // 9) 코넥스 회사는 이전상장구분 필수
    if (scwin.mktTpCd === "6" && $c.util.isEmpty(dma_mst.get("preListTpCd"))) {
        await $c.win.alert("[이전상장구분(코넥스)]를 선택하세요.");
        cmb_PRE_LIST_TP_CD.focus();
        return false;
    }

    return true;
};

/**
 * @method
 * @name scwin.validatePeriod
 * @author Inswave
 * @date 2026. 10. 28
 * @description 선택 입력 기간 검증 — 둘 다 비면 통과, 하나만 있으면 나머지 필수, 시작일이 종료일보다 늦으면 실패(같은 날은 통과).
 * (원본 fn_CheckForm 의 예고기간·정리매매기간 + compareFromToDate — §6.11)
 * @param {Object} strtCal 시작일 달력
 * @param {Object} endCal 종료일 달력
 * @param {String} strtNm 시작일 이름 (안내용)
 * @param {String} endNm 종료일 이름 (안내용)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validatePeriod = async function (strtCal, endCal, strtNm, endNm) {
    const strtDd = strtCal.getValue();
    const endDd = endCal.getValue();

    if ($c.util.isEmpty(strtDd) && $c.util.isEmpty(endDd)) return true;

    if ($c.util.isEmpty(strtDd)) {
        await $c.win.alert("[" + strtNm + "]을 입력하세요.");
        strtCal.focus();
        return false;
    }
    if ($c.util.isEmpty(endDd)) {
        await $c.win.alert("[" + endNm + "]을 입력하세요.");
        endCal.focus();
        return false;
    }
    if (strtDd > endDd) {
        await $c.win.alert(strtNm + "을(를) " + endNm + " 이전으로 선택하세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 28
 * @description 업무처리번호를 새로 받는다. $c.stf.getNewBzProcNo 는 응답 봉투를 그대로 돌려줄 수 있어 body 를 꺼내고,
 * body 가 문자열이면 그대로, 객체면 bzProcsNo 를 문자열로 만든다. 14자리 검사는 호출부(scwin.save)가 한다. (§5.4)
 * @returns {Promise<String>} 업무처리번호 (실패면 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // TODO: 채번 응답 모양 미확정 — body 가 문자열인지 { bzProcsNo } 인지 확인 (§10 #5). 지금은 둘 다 받는다.
    const res = await $c.stf.getNewBzProcNo();
    const body = res?.body ?? res;
    return String((typeof body === "object" && body !== null) ? (body.bzProcsNo ?? "") : (body ?? ""));
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 저장. 검증 → 확인 → 채번 → 전송 순서 (원본 fn_save — §6.12, §1.4 업무 4)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    dma_mst.set("bzProcsNo", bzProcsNo);
    dma_mst.set("isurCd", scwin.isurCd);
    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정. 검증 → 확인 → 전송 순서. 원본도 변경 여부를 확인하지 않는다. (원본 fn_update — §6.12, §1.4 업무 5)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제. 시장안내공시가 이미 승인된 건이면 막고, 확인을 받은 뒤 전송한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.12, §1.4 업무 6)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    // TODO: pcc checkDeleteDiscls 는 target 을 문자열로 조립(dtsObj + "=body")하면서 dtsObj.get 도 부른다 —
    //       dataMap 을 넘기면 target 이 깨지는 결함, pcc 수정 요청 (§10 #9)
    if (!await $c.lc.checkDeleteDiscls(dma_bzCheck, scwin.bzProcsNo)) return;

    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.checkBiz
 * @author Inswave
 * @date 2026. 10. 28
 * @description 안내문작성·기안 전 확인 — 회사와 상장폐지 건(업무처리번호)을 골랐는가. (원본 fn_CheckBiz — §6.13)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkBiz = async function () {
    if ($c.util.isEmpty(scwin.isurCd)) {
        await $c.win.alert("[회사]를 선택하세요.");
        return false;
    }
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        await $c.win.alert("[대상]를 선택하세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.getDsclFormCd
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문 서식코드. 유가 68051A, 코스닥·코넥스는 투자회사(MF)면 액면가로 70794/70794_P, 아니면 코스닥 70769·코넥스 32007. (원본 fn_dscl — §6.10)
 * @returns {String} 서식코드 (시장구분이 1·2·6 이 아니면 빈 문자열)
 * @hidden N
 */
scwin.getDsclFormCd = function () {
    if (scwin.mktTpCd === "1") return scwin.DSCL_FORM_CD_KSE;
    if (scwin.mktTpCd !== "2" && scwin.mktTpCd !== "6") return "";

    if (scwin.secugrpId === $c.lc.glb.SECUGRP_ID_MF) {
        // 액면가가 0(무액면)인지 첫 종목으로 본다 — 종목이 없으면 원본처럼 무액면
        return (Number(dlt_list.getCellData(0, "parval") || 0) !== 0) ? scwin.DSCL_FORM_CD_MF : scwin.DSCL_FORM_CD_MF_NPARVAL;
    }
    return (scwin.mktTpCd === "2") ? scwin.DSCL_FORM_CD_KOSDAQ : scwin.DSCL_FORM_CD_KONEX;
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr[0..3] 과 데이터셋 4개다. (§6.10)
 * 코넥스 회사에서 특례상장구분을 골랐으면 마스터의 상장주선인명을 그 이름으로 바꿔 넘긴다(화면 값은 바꾸지 않음 — §8 #8).
 * @returns {Object} 넘길 data (서식코드를 정할 수 없으면 null)
 * @hidden N
 */
scwin.getDsclData = function () {
    const formCd = scwin.getDsclFormCd();
    if ($c.util.isEmpty(formCd)) return null;

    const mst = { ...dma_mst.getJSON() };
    if (scwin.mktTpCd === "6" && !$c.util.isEmpty(cmb_SPECL_LIST_TP_CD.getValue())) {
        mst.mktpartcKorNm = cmb_SPECL_LIST_TP_CD.getText();
    }

    return {
        formCd : formCd,                    // AS-IS arr[0]
        bzProcsNo : scwin.bzProcsNo,        // AS-IS arr[1]
        isurCd : scwin.isurCd,              // AS-IS arr[2]
        mktId : scwin.mktTpCd,              // AS-IS arr[3]
        isu : dlt_list.getAllJSON(),        // AS-IS CopyDataSet(dts_Isu, param_dts_isu)
        mst : [mst],                        // AS-IS CopyDataSet(dts_Mst, param_dts_mst)
        // TODO: 영문 마스터·종목(masterDetailEng·listMarketEng) API 명세 없음 — 빈 목록으로 넘긴다 (§10 #2)
        isuEng : [],                        // AS-IS CopyDataSet(dts_Isu_Eng, param_dts_isu_eng)
        mstEng : []                         // AS-IS CopyDataSet(dts_Mst_Eng, param_dts_mst_eng)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린 뒤 상장폐지내역을 다시 조회한다. (원본 fn_dscl — §6.10, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    if (!await scwin.checkBiz()) return;

    // 상세를 고친 뒤 저장하지 않았으면 안내 — MSG-0022 "변경된 항목이 있습니다. 수정후에 안내문작성을 다시 클릭하세요."
    if (scwin.getEditState() !== scwin.savedState) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }

    const data = scwin.getDsclData();
    if (!data) {
        // TODO: 시장구분 1·2·6 외 처리·문구는 가정 (§8 #7, §10 #10)
        await $c.win.alert("안내문을 작성할 수 없는 시장구분입니다.");
        return;
    }

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 755,
        height : 815,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #8)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, data);

    // 원본도 창이 닫힌 뒤 내역을 다시 조회한다(fn_list_sync) — 상세는 빈 상태(신규)가 된다.
    await scwin.listSync();
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 28
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.10, §10 #8, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 회사코드 [3] 시장구분 을 채운다
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (쓰지 않음)
 * @param {Object} dlt3 92024 의 원천 자료 3 (쓰지 않음)
 * @param {Object} dlt4 92024 의 원천 자료 4 (쓰지 않음)
 * @param {Object} dltIsuEng 92024 의 영문 종목 dataList
 * @param {Object} dltMstEng 92024 의 영문 마스터 dataList
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst, dlt2, dlt3, dlt4, dltIsuEng, dltMstEng) {
    const data = scwin.getDsclData();
    if (!data) return arr.length;

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);
    scwin.fillDataList(dltIsuEng, data.isuEng);
    scwin.fillDataList(dltMstEng, data.mstEng);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 컬럼 정의가 비어 있는 다른 화면의 dataList 에 행을 채운다. setJSON 은 선언된 컬럼만 옮기므로 첫 행의 키로 컬럼을 먼저 만든다.
 * (92024 의 원천 자료 dataList 는 서식마다 컬럼이 달라 부모가 컬럼째 넘긴다 — 원본 CopyDataSet)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};

/**
 * @method
 * @name scwin.writeDraft
 * @author Inswave
 * @date 2026. 10. 28
 * @description 기안문작성 팝업을 업무처리번호와 함께 열고 닫힐 때까지 기다린다. (원본 fn_drft — §6.13)
 * pcc $c.lc.popFindDraft 는 값을 넘기지 않는 콜백형이라 쓰지 않는다.
 * @returns
 * @hidden N
 */
scwin.writeDraft = async function () {
    if (!await scwin.checkBiz()) return;

    const options = {
        id : "ULDSTF92004",
        popupName : "기안문작성",
        width : 888,
        height : 730,
        type : "pageFramePopup"
    };

    // TODO: 기안 팝업 전환본이 없어 경로·수신 키(bzProcsNo)는 가정 (§10 #8)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92004.xml", options, { bzProcsNo : scwin.bzProcsNo });
};
